import{_ as o,o as a,c as s,ag as r}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Estações","description":"","frontmatter":{},"headers":[],"relativePath":"pt/repair-station/stations.md","filePath":"pt/repair-station/stations.md"}'),t={name:"pt/repair-station/stations.md"};function i(c,e,d,n,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="estacoes" tabindex="-1">Estações <a class="header-anchor" href="#estacoes" aria-label="Permalink to &quot;Estações&quot;">​</a></h1><p>Uma estação é uma zona de paragem para veículos, com um raio, uma percentagem de preço e, se quiser, um prop como uma caixa de ferramentas colocada ao lado. Três estações vêm prontas: <strong>Hayes Autos</strong>, <strong>Sandy Shores</strong> e <strong>Paleto Bay</strong>.</p><h2 id="como-decorre-uma-reparacao" tabindex="-1">Como decorre uma reparação <a class="header-anchor" href="#como-decorre-uma-reparacao" aria-label="Permalink to &quot;Como decorre uma reparação&quot;">​</a></h2><ol><li>O condutor para dentro do raio da estação. Um aviso mostra o preço mais baixo.</li><li><strong>E</strong> abre o menu de reparação com os danos do veículo e os serviços, com os respetivos preços (descontos por profissão e percentagem da estação incluídos).</li><li>O preço é pago, o motor desliga-se e o capô abre. Uma barra de progresso corre durante o serviço, com som e faíscas. Prima <strong>X</strong> para cancelar.</li><li>No fim, as partes reparadas ficam arranjadas e o veículo pode sair.</li></ol><p>A estação recusa a reparação quando:</p><ul><li>a estação está fechada, ou <code>Enabled</code> está desativado;</li><li>o jogador não conduz o veículo, ou o veículo não está na zona da estação;</li><li>o veículo está em movimento;</li><li>a estação já está em uso (um veículo de cada vez);</li><li>a classe do veículo está bloqueada (<code>BlockedClasses</code>);</li><li>o serviço não repara nada neste veículo e <code>RequireDamage</code> está ativado;</li><li>o jogador tem de esperar o tempo de espera (<code>CooldownSeconds</code>);</li><li>há mecânicos em serviço, veja abaixo;</li><li>o jogador não pode pagar.</li></ul><p>Se o jogador sair do veículo, se afastar ou cancelar, ou se a estação for fechada ou eliminada durante a reparação, a reparação pára e o jogador é reembolsado do valor cobrado, na conta cobrada.</p><h2 id="mecanicos-em-servico" tabindex="-1">Mecânicos em serviço <a class="header-anchor" href="#mecanicos-em-servico" aria-label="Permalink to &quot;Mecânicos em serviço&quot;">​</a></h2><p>Os jogadores que têm uma oficina não devem perder clientes para uma estação. Indique as suas profissões em <code>MechanicJobs</code> e defina <code>MaxMechanicsOnDuty</code>: enquanto houver esse número de mecânicos ou mais em serviço, todas as estações ficam fechadas e pedem aos jogadores que os chamem. Com <code>0</code>, as estações nunca fecham por este motivo.</p><h2 id="o-editor-de-estacoes" tabindex="-1">O editor de estações <a class="header-anchor" href="#o-editor-de-estacoes" aria-label="Permalink to &quot;O editor de estações&quot;">​</a></h2><p>Abra-o com <code>/nay:repair</code>, ou com <strong>Gerir estações</strong> na página Repair Station do <code>/nay</code>. Requer o scope <code>nay_repair.config</code>.</p><ol><li><strong>Nova estação aqui</strong>: coloque-se onde os veículos devem parar, no veículo ou a pé. A estação assume a sua posição e a sua direção.</li><li>Escolha a posição do veículo ou a do prop e mova-a: <ul><li>setas: frente, trás, esquerda, direita, consoante a câmara;</li><li>Page Up / Page Down: altura;</li><li>Q / E: rodar;</li><li>Shift: passos finos.</li></ul></li><li><strong>Para a minha posição</strong> e <strong>Para o chão</strong> colocam o elemento selecionado.</li><li>Defina o nome, o raio, a percentagem de preço, o blip e o prop. Props sugeridos: <code>prop_toolchest_05</code>, <code>prop_toolchest_01</code>, <code>prop_carcreeper</code>, <code>prop_compressor_03</code>, ou qualquer nome de modelo.</li><li><strong>Enter</strong> guarda, <strong>Retrocesso</strong> cancela. A estação fica ativa para todos os jogadores de imediato.</li></ol><p>O gestor também permite ir a uma estação, abri-la ou fechá-la e eliminá-la (prima duas vezes para confirmar). O editor preenche a definição <code>Stations</code>, descrita na página <a href="/pt/repair-station/settings#stations">Definições</a>. Cada estação recebe um identificador que nunca muda.</p>',13)])])}const g=o(t,[["render",i]]);export{u as __pageData,g as default};
